def create_object(type, location=None, label=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0099000" if __import__("os").path.isdir("./environment_mix/0099000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    inv_file = "ue_tool_invocations.json"
    sess_file = "ue_sessions.json"
    actors_file = "ue_actors.json"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def _validate_vec3(v, field):
        if v is None:
            return None
        if not isinstance(v, list) or len(v) != 3 or not all(_is_num(x) for x in v):
            return _err("VALIDATION_ERROR", f"{field} must be a 3-number vector.")
        return None

    def _resolve_session():
        sessions = _load(sess_file)
        connected = [s for s in sessions if isinstance(s, dict) and s.get("status") == "connected" and isinstance(s.get("id"), str) and s.get("id")]
        if len(connected) == 0:
            return None, _err("UNAUTHORIZED", "No connected Unreal session available to service this request.")
        # relaxed: choose most recently updated/heartbeat
        def _iso_to_dt(x):
            if not isinstance(x, str) or not x:
                return datetime.datetime.min
            try:
                if x.endswith("Z"): x = x[:-1]
                return datetime.datetime.fromisoformat(x)
            except Exception:
                return datetime.datetime.min
        connected.sort(key=lambda s: (_iso_to_dt(s.get("last_heartbeat_at")), _iso_to_dt(s.get("updated_at"))), reverse=True)
        return connected[0], None

    def _append_invocation(session_id, req_params):
        invs = _load(inv_file)
        inv = {
            "id": _new_id("ueinv"),
            "session_id": session_id,
            "tool_name": "create_object",
            "request_params": req_params,
            "status": "received",
            "result": None,
            "error": None,
            "started_at": None,
            "finished_at": None,
            "duration_ms": None,
            "python_code": None,
            "python_file": None,
            "ctx": None,
            "created_at": now,
            "updated_at": now,
        }
        invs.append(inv)
        _save(inv_file, invs)
        return inv["id"]

    def _patch_invocation(inv_id, patch):
        invs = _load(inv_file)
        for r in invs:
            if isinstance(r, dict) and r.get("id") == inv_id:
                r.update(patch)
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                _save(inv_file, invs)
                return True
        return False

    if not isinstance(type, str) or not type.strip():
        return _err("VALIDATION_ERROR", "type must be a non-empty string.")
    if label is not None and not isinstance(label, str):
        return _err("VALIDATION_ERROR", "label must be a string or null.")
    verr = _validate_vec3(location, "location")
    if verr:
        return verr

    sess, serr = _resolve_session()
    if serr:
        inv_id = _append_invocation("unknown", {"type": type, "location": location, "label": label})
        _patch_invocation(inv_id, {
            "status": "failed",
            "started_at": now,
            "finished_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "duration_ms": int((time.time() - t0) * 1000),
            "error": serr["error"],
        })
        return serr

    session_id = sess["id"]
    inv_id = _append_invocation(session_id, {"type": type, "location": location, "label": label})
    _patch_invocation(inv_id, {"status": "running", "started_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"})

    # NOT_FOUND if no active level/world loaded
    if not (isinstance(sess.get("map_path"), str) and sess.get("map_path")) and not (isinstance(sess.get("map_name"), str) and sess.get("map_name")):
        err = _err("NOT_FOUND", "No active level/world is loaded for the current session.")
        _patch_invocation(inv_id, {
            "status": "failed",
            "finished_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "duration_ms": int((time.time() - t0) * 1000),
            "error": err["error"],
        })
        return err

    actors = _load(actors_file)

    # Unique(session_id, name): generate a unique name if needed
    base_name = type.strip()
    existing_names = set(a.get("name") for a in actors if isinstance(a, dict) and a.get("session_id") == session_id and isinstance(a.get("name"), str))
    name = base_name
    if name in existing_names:
        i = 2
        while f"{base_name}_{i}" in existing_names:
            i += 1
        name = f"{base_name}_{i}"

    actor_id = _new_id("ue_act")
    actor_row = {
        "id": actor_id,
        "session_id": session_id,
        "name": name,
        "label": label,
        "actor_type": type.strip(),
        "location": location,
        "rotation": None,
        "scale": None,
        "status": "active",
        "created_at": now,
        "updated_at": now,
        "deleted_at": None,
    }
    actors.append(actor_row)
    _save(actors_file, actors)

    result = {
        "id": actor_row["id"],
        "name": actor_row["name"],
        "label": actor_row.get("label"),
        "type": actor_row.get("actor_type"),
        "location": actor_row.get("location"),
        "status": actor_row.get("status"),
    }
    _patch_invocation(inv_id, {
        "status": "succeeded",
        "finished_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        "duration_ms": int((time.time() - t0) * 1000),
        "result": result,
        "error": None,
    })
    return result

def create_material(package_path, name, properties=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0099000" if __import__("os").path.isdir("./environment_mix/0099000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    inv_file = "ue_tool_invocations.json"
    sess_file = "ue_sessions.json"
    mat_file = "ue_materials.json"

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _resolve_session():
        sessions = _load(sess_file)
        connected = [s for s in sessions if isinstance(s, dict) and s.get("status") == "connected" and isinstance(s.get("id"), str) and s.get("id")]
        if len(connected) == 0:
            return None, _err("UNAUTHORIZED", "No connected Unreal session available to service this request.")
        def _iso_to_dt(x):
            if not isinstance(x, str) or not x:
                return datetime.datetime.min
            try:
                if x.endswith("Z"): x = x[:-1]
                return datetime.datetime.fromisoformat(x)
            except Exception:
                return datetime.datetime.min
        connected.sort(key=lambda s: (_iso_to_dt(s.get("last_heartbeat_at")), _iso_to_dt(s.get("updated_at"))), reverse=True)
        return connected[0], None

    def _append_invocation(session_id, req_params):
        invs = _load(inv_file)
        inv = {
            "id": _new_id("ueinv"),
            "session_id": session_id,
            "tool_name": "create_material",
            "request_params": req_params,
            "status": "received",
            "result": None,
            "error": None,
            "started_at": None,
            "finished_at": None,
            "duration_ms": None,
            "python_code": None,
            "python_file": None,
            "ctx": None,
            "created_at": now,
            "updated_at": now,
        }
        invs.append(inv)
        _save(inv_file, invs)
        return inv["id"]

    def _patch_invocation(inv_id, patch):
        invs = _load(inv_file)
        for r in invs:
            if isinstance(r, dict) and r.get("id") == inv_id:
                r.update(patch)
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                _save(inv_file, invs)
                return True
        return False

    if not isinstance(package_path, str) or not package_path.strip():
        return _err("VALIDATION_ERROR", "package_path must be a non-empty string.")
    if not package_path.startswith("/Game/"):
        return _err("VALIDATION_ERROR", "package_path must start with '/Game/' (rule: package_path like '/Game/%').")
    if not isinstance(name, str) or not name.strip():
        return _err("VALIDATION_ERROR", "name must be a non-empty string.")
    if properties is not None and not isinstance(properties, dict):
        return _err("VALIDATION_ERROR", "properties must be an object or null.")

    sess, serr = _resolve_session()
    if serr:
        inv_id = _append_invocation("unknown", {"package_path": package_path, "name": name, "properties": properties})
        _patch_invocation(inv_id, {
            "status": "failed",
            "started_at": now,
            "finished_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "duration_ms": int((time.time() - t0) * 1000),
            "error": serr["error"],
        })
        return serr

    session_id = sess["id"]
    inv_id = _append_invocation(session_id, {"package_path": package_path, "name": name, "properties": properties})
    _patch_invocation(inv_id, {"status": "running", "started_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"})

    # NOT_FOUND if no active level/world loaded (same gating as other scene tools)
    if not (isinstance(sess.get("map_path"), str) and sess.get("map_path")) and not (isinstance(sess.get("map_name"), str) and sess.get("map_name")):
        err = _err("NOT_FOUND", "No active level/world is loaded for the current session.")
        _patch_invocation(inv_id, {
            "status": "failed",
            "finished_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
            "duration_ms": int((time.time() - t0) * 1000),
            "error": err["error"],
        })
        return err

    # Build path = package_path + '/' + name (avoid double slashes)
    pkg = package_path.rstrip("/")
    mat_name = name.strip().strip("/")
    path = pkg + "/" + mat_name

    mats = _load(mat_file)
    for m in mats:
        if isinstance(m, dict) and m.get("session_id") == session_id and m.get("path") == path and m.get("status") == "active":
            err = _err("CONFLICT", "Material already exists at path for this session (rule: unique(session_id, path) among active).", path=path)
            _patch_invocation(inv_id, {
                "status": "failed",
                "finished_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
                "duration_ms": int((time.time() - t0) * 1000),
                "error": err["error"],
            })
            return err

    shading_model = None
    blend_mode = None
    two_sided = None
    if isinstance(properties, dict):
        if "shading_model" in properties:
            shading_model = properties.get("shading_model")
        if "blend_mode" in properties:
            blend_mode = properties.get("blend_mode")
        if "two_sided" in properties:
            two_sided = properties.get("two_sided")

    # Validate extracted enums if present
    allowed_shading = {"DefaultLit", "Unlit", "Subsurface", "TwoSidedFoliage", "PreintegratedSkin", "ClearCoat", "Cloth", "Eye", "SingleLayerWater", "ThinTranslucent"}
    allowed_blend = {"Opaque", "Masked", "Translucent", "Additive", "Modulate", "AlphaComposite", "AlphaHoldout"}
    if shading_model is not None and shading_model not in allowed_shading:
        err = _err("VALIDATION_ERROR", "properties.shading_model is not a supported enum value.", allowed=sorted(list(allowed_shading)))
        _patch_invocation(inv_id, {"status": "failed", "finished_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
                                   "duration_ms": int((time.time() - t0) * 1000), "error": err["error"]})
        return err
    if blend_mode is not None and blend_mode not in allowed_blend:
        err = _err("VALIDATION_ERROR", "properties.blend_mode is not a supported enum value.", allowed=sorted(list(allowed_blend)))
        _patch_invocation(inv_id, {"status": "failed", "finished_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
                                   "duration_ms": int((time.time() - t0) * 1000), "error": err["error"]})
        return err
    if two_sided is not None and not isinstance(two_sided, bool):
        err = _err("VALIDATION_ERROR", "properties.two_sided must be a boolean when provided.")
        _patch_invocation(inv_id, {"status": "failed", "finished_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
                                   "duration_ms": int((time.time() - t0) * 1000), "error": err["error"]})
        return err

    mat_row = {
        "id": _new_id("ue_mat"),
        "session_id": session_id,
        "package_path": pkg,
        "name": mat_name,
        "path": path,
        "properties": properties,
        "shading_model": shading_model,
        "blend_mode": blend_mode,
        "two_sided": two_sided,
        "status": "active",
        "created_at": now,
        "updated_at": now,
        "deleted_at": None,
    }
    mats.append(mat_row)
    _save(mat_file, mats)

    result = {
        "id": mat_row["id"],
        "name": mat_row["name"],
        "path": mat_row["path"],
        "package_path": mat_row["package_path"],
        "shading_model": mat_row.get("shading_model"),
        "blend_mode": mat_row.get("blend_mode"),
        "two_sided": mat_row.get("two_sided"),
        "properties": mat_row.get("properties"),
        "status": mat_row.get("status"),
    }
    _patch_invocation(inv_id, {
        "status": "succeeded",
        "finished_at": datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z",
        "duration_ms": int((time.time() - t0) * 1000),
        "result": result,
        "error": None,
    })
    return result

def modify_material(path, properties, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0099000" if __import__("os").path.isdir("./environment_mix/0099000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    inv_file = "ue_tool_invocations.json"
    sess_file = "ue_sessions.json"
    mat_file = "ue_materials.json"

    def _new_id(prefix):
        return f"{prefix}_01{uuid.uuid4().hex[:25].upper()}"

    def _iso_to_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _resolve_session_best_for_material(target_path):
        sessions = _load(sess_file)
        connected = [s for s in sessions if isinstance(s, dict) and s.get("status") == "connected" and isinstance(s.get("id"), str) and s.get("id")]
        if not connected:
            return None, _err("UNAUTHORIZED", "No connected Unreal session available to service this request.")
        mats = _load(mat_file)
        candidates = []
        for s in connected:
            sid = s["id"]
            for m in mats:
                if isinstance(m, dict) and m.get("session_id") == sid and m.get("path") == target_path and m.get("status") == "active":
                    candidates.append(s)
                    break
        if not candidates:
            # Fall back to most recent connected session; the material may still be there but in another state.
            connected.sort(key=lambda s: (
                _iso_to_dt(s.get("last_heartbeat_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc),
                _iso_to_dt(s.get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc),
                _iso_to_dt(s.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc),
            ), reverse=True)
            return connected[0], None
        candidates.sort(key=lambda s: (
            _iso_to_dt(s.get("last_heartbeat_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc),
            _iso_to_dt(s.get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc),
            _iso_to_dt(s.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc),
        ), reverse=True)
        return candidates[0], None

    def _append_invocation(session_id_val, req_params):
        invs = _load(inv_file)
        inv = {
            "id": _new_id("ueinv"),
            "session_id": session_id_val,
            "tool_name": "modify_material",
            "request_params": req_params,
            "status": "received",
            "result": None,
            "error": None,
            "started_at": None,
            "finished_at": None,
            "duration_ms": None,
            "python_code": None,
            "python_file": None,
            "ctx": None,
            "created_at": now,
            "updated_at": now,
        }
        invs.append(inv)
        _save(inv_file, invs)
        return inv["id"]

    def _patch_invocation(inv_id, patch):
        invs = _load(inv_file)
        for r in invs:
            if isinstance(r, dict) and r.get("id") == inv_id:
                r.update(patch)
                r["updated_at"] = now
                _save(inv_file, invs)
                return True
        return False

    # Validate inputs
    if not isinstance(path, str) or not path.strip():
        return _err("VALIDATION_ERROR", "path is required and must be a non-empty string.", field="path")
    path = path.strip()
    if not path.startswith("/Game/"):
        return _err("VALIDATION_ERROR", "path must start with '/Game/'.", field="path")

    if not isinstance(properties, dict):
        return _err("VALIDATION_ERROR", "properties must be an object.", field="properties")

    session, serr = _resolve_session_best_for_material(path)
    if serr:
        return serr
    session_id = session["id"]

    inv_id = _append_invocation(session_id, {"path": path, "properties": properties})
    started = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _patch_invocation(inv_id, {"status": "running", "started_at": started})

    mats = _load(mat_file)

    # If the exact path exists active in ANY connected session and we picked wrong, correct to that session.
    # This avoids "valid request rejected due to wrong session resolution".
    if not any(isinstance(m, dict) and m.get("session_id") == session_id and m.get("path") == path and m.get("status") == "active" for m in mats):
        sessions = _load(sess_file)
        connected_ids = [s.get("id") for s in sessions if isinstance(s, dict) and s.get("status") == "connected" and isinstance(s.get("id"), str)]
        found_sid = None
        for sid in connected_ids:
            for m in mats:
                if isinstance(m, dict) and m.get("session_id") == sid and m.get("path") == path and m.get("status") == "active":
                    found_sid = sid
                    break
            if found_sid:
                break
        if found_sid:
            session_id = found_sid

    target = None
    for m in mats:
        if isinstance(m, dict) and m.get("session_id") == session_id and m.get("path") == path and m.get("status") == "active":
            target = m
            break

    if target is None:
        finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        err = _err("NOT_FOUND", "No active material exists at the given path for this session.", path=path)
        _patch_invocation(inv_id, {
            "status": "failed",
            "error": err["error"],
            "finished_at": finished,
            "duration_ms": int(max(0, round((time.time() - t0) * 1000))),
        })
        return err

    # Merge properties (empty {} is valid and should still "touch" updated_at)
    stored_props = target.get("properties")
    if not isinstance(stored_props, dict):
        stored_props = {}
    for k, v in properties.items():
        stored_props[k] = v
    target["properties"] = stored_props

    # Sync common extracted fields when present in properties
    if "shading_model" in properties:
        target["shading_model"] = properties.get("shading_model")
    if "blend_mode" in properties:
        target["blend_mode"] = properties.get("blend_mode")
    if "two_sided" in properties:
        target["two_sided"] = properties.get("two_sided")

    target["updated_at"] = now

    _save(mat_file, mats)

    result = {
        "material": {
            "id": target.get("id"),
            "name": target.get("name"),
            "path": target.get("path"),
            "package_path": target.get("package_path"),
            "shading_model": target.get("shading_model"),
            "blend_mode": target.get("blend_mode"),
            "two_sided": target.get("two_sided"),
            "properties": target.get("properties"),
            "status": target.get("status"),
            "updated_at": target.get("updated_at"),
        },
        "duration_ms": int(max(0, round((time.time() - t0) * 1000))),
    }

    finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _patch_invocation(inv_id, {
        "status": "succeeded",
        "result": result,
        "finished_at": finished,
        "duration_ms": result["duration_ms"],
    })
    return result

