def list_sessions(status=None, project_name=None, map_path=None, engine_version=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0099000" if __import__("os").path.isdir("./environment_mix/0099000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # Validate filters/pagination
    if status is not None and status not in ("connected", "disconnected", "expired"):
        return _err("VALIDATION_ERROR", "Invalid status filter.", field="status")
    if project_name is not None and not isinstance(project_name, str):
        return _err("VALIDATION_ERROR", "project_name must be a string or null.", field="project_name")
    if map_path is not None and not isinstance(map_path, str):
        return _err("VALIDATION_ERROR", "map_path must be a string or null.", field="map_path")
    if engine_version is not None and not isinstance(engine_version, str):
        return _err("VALIDATION_ERROR", "engine_version must be a string or null.", field="engine_version")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")

    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string or null.", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or obj.get("v") != 1 or not isinstance(obj.get("start"), int) or obj["start"] < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            start = obj["start"]
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    sessions = _load("ue_sessions.json")

    # "UNAUTHORIZED if caller cannot enumerate sessions": no auth model exists; allow enumeration
    rows = []
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if status is not None and s.get("status") != status:
            continue
        if project_name is not None and s.get("project_name") != project_name:
            continue
        if map_path is not None and s.get("map_path") != map_path:
            continue
        if engine_version is not None and s.get("engine_version") != engine_version:
            continue
        rows.append(s)

    def _dt(v):
        if not isinstance(v, str) or not v:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        try:
            return datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
        except Exception:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    rows.sort(key=lambda r: _dt(r.get("updated_at")), reverse=True)

    total = len(rows)
    page = rows[start:start + limit]
    next_start = start + len(page)
    has_more = next_start < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"v": 1, "start": next_start}, separators=(",", ":"))
        next_cursor = base64.urlsafe_b64encode(payload.encode("utf-8")).decode("utf-8")

    return {
        "data": page,
        "total": total,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "duration_ms": int(max(0, round((time.time() - t0) * 1000))),
    }

def set_session_status(session_id, status, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0099000" if __import__("os").path.isdir("./environment_mix/0099000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(session_id, str) or not session_id.strip():
        return _err("VALIDATION_ERROR", "session_id must be a non-empty string.", field="session_id")
    session_id = session_id.strip()

    if status not in ("connected", "disconnected", "expired"):
        return _err("VALIDATION_ERROR", "status must be one of: connected, disconnected, expired.", field="status")

    sessions = _load("ue_sessions.json")

    sess = None
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == session_id:
            sess = s
            break
    if sess is None:
        return _err("NOT_FOUND", "Session not found.", session_id=session_id)

    cur = sess.get("status")
    allowed = {
        "connected": {"disconnected", "expired"},
        "disconnected": {"connected", "expired"},
        "expired": set(),
    }
    if cur not in allowed:
        return _err("CONFLICT", "Session is in an unknown lifecycle state.", current_status=cur)

    if status == cur:
        # Idempotent: still produce an observable effect by updating updated_at (management action).
        sess["updated_at"] = now
        # Keep constraint last_heartbeat_at <= updated_at
        lhb = sess.get("last_heartbeat_at")
        if isinstance(lhb, str) and lhb:
            try:
                lhb_dt = datetime.datetime.fromisoformat(lhb.replace("Z", "+00:00"))
                upd_dt = datetime.datetime.fromisoformat(now.replace("Z", "+00:00"))
                if lhb_dt > upd_dt:
                    sess["last_heartbeat_at"] = now
            except Exception:
                pass
        _save("ue_sessions.json", sessions)
        return {"session": sess, "duration_ms": int(max(0, round((time.time() - t0) * 1000))), "idempotent": True}

    if status not in allowed[cur]:
        return _err("INVALID_TRANSITION", "Requested status transition is not allowed by lifecycle rules.", current_status=cur, requested_status=status)

    sess["status"] = status
    sess["updated_at"] = now
    # Keep constraint last_heartbeat_at <= updated_at OR NULL
    lhb = sess.get("last_heartbeat_at")
    if isinstance(lhb, str) and lhb:
        try:
            lhb_dt = datetime.datetime.fromisoformat(lhb.replace("Z", "+00:00"))
            upd_dt = datetime.datetime.fromisoformat(now.replace("Z", "+00:00"))
            if lhb_dt > upd_dt:
                sess["last_heartbeat_at"] = now
        except Exception:
            # If parse fails, leave as-is; constraint can't be enforced reliably.
            pass

    _save("ue_sessions.json", sessions)

    return {"session": sess, "duration_ms": int(max(0, round((time.time() - t0) * 1000))), "idempotent": False}

