        connected.sort(key=lambda s: (
            _iso_to_dt(s.get("last_heartbeat_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc),
            _iso_to_dt(s.get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc),
            _iso_to_dt(s.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc),
        ), reverse=True)
        return connected[0], None

    def _append_invocation(session_id_val, req_params):
        invs = _load(inv_file)
        inv = {
            "id": _new_id(),
            "session_id": session_id_val,
            # Not in enum; log as closest read tool for audit compatibility
            "tool_name": "get_scene_info",
            "request_params": req_params,
            "status": "received",
            "result": None,
            "error": None,
            "started_at": None,
            "finished_at": None,
            "duration_ms": None,
            "python_code": None,
            "python_file": None,
            "ctx": None,
            "created_at": now,
            "updated_at": now,
        }
        invs.append(inv)
        _save(inv_file, invs)
        return inv["id"]

    def _patch_invocation(inv_id, patch):
        invs = _load(inv_file)
        for r in invs:
            if isinstance(r, dict) and r.get("id") == inv_id:
                r.update(patch)
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                _save(inv_file, invs)
                return True
        return False

    # Validate inputs
    if status is None:
        status = "active"
    if status not in ("active", "deleted"):
        return _err("VALIDATION_ERROR", "status must be 'active' or 'deleted'.", field="status")
    if name_prefix is not None and not isinstance(name_prefix, str):
        return _err("VALIDATION_ERROR", "name_prefix must be a string or null.", field="name_prefix")
    if actor_type is not None and not isinstance(actor_type, str):
        return _err("VALIDATION_ERROR", "actor_type must be a string or null.", field="actor_type")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500.", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string or null.", field="cursor")

    session, serr = _resolve_session(session_id)
    if serr:
        return serr
    sid = session["id"]

    inv_id = _append_invocation(sid, {"session_id": session_id, "status": status, "name_prefix": name_prefix, "actor_type": actor_type, "limit": limit, "cursor": cursor})
    started = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _patch_invocation(inv_id, {"status": "running", "started_at": started})

    actors = [a for a in _load(actors_file) if isinstance(a, dict) and a.get("session_id") == sid]

    # Filters
    actors = [a for a in actors if a.get("status") == status]
    if name_prefix is not None:
        actors = [a for a in actors if isinstance(a.get("name"), str) and a["name"].startswith(name_prefix)]
    if actor_type is not None:
        actors = [a for a in actors if a.get("actor_type") == actor_type]

    # Stable sort by name then created_at
    actors.sort(key=lambda a: ((a.get("name") or ""), (a.get("created_at") or "")))

    # Cursor is base64-encoded integer offset
    offset = 0
    if cursor:
        try:
            decoded = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            offset = int(decoded)
            if offset < 0:
                offset = 0
        except Exception:
            finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            err = _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            _patch_invocation(inv_id, {"status": "failed", "error": err["error"], "finished_at": finished, "duration_ms": int(max(0, round((time.time() - t0) * 1000)))})
            return err

    page = actors[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < len(actors)
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "objects": page,
        "total": len(actors),
        "has_more": has_more,
        "next_cursor": next_cursor,
        "duration_ms": int(max(0, round((time.time() - t0) * 1000))),
    }

    finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _patch_invocation(inv_id, {"status": "succeeded", "result": resp, "finished_at": finished, "duration_ms": resp["duration_ms"]})
    return resp

def list_materials(session_id=None, status=None, package_path=None, path_prefix=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0099000" if __import__("os").path.isdir("./environment_mix/0099000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    inv_file = "ue_tool_invocations.json"
    sess_file = "ue_sessions.json"
    mats_file = "ue_materials.json"

    def _resolve_session(explicit_id):
        sessions = _load(sess_file)
        if explicit_id is not None:
            if not isinstance(explicit_id, str) or not explicit_id:
                return None, _err("VALIDATION_ERROR", "session_id must be a string or null.")
            for s in sessions:
                if isinstance(s, dict) and s.get("id") == explicit_id:
                    return s, None
            return None, _err("NOT_FOUND", "session_id not found.", session_id=explicit_id)
        connected = [s for s in sessions if isinstance(s, dict) and s.get("status") == "connected" and isinstance(s.get("id"), str) and s.get("id")]
        if len(connected) == 0:
            return None, _err("UNAUTHORIZED", "No connected Unreal session available to service this request.")
        def _iso_to_dt(x):
            if not isinstance(x, str) or not x:
                return datetime.datetime.min
            try:
                if x.endswith("Z"): x = x[:-1]
                return datetime.datetime.fromisoformat(x)
            except Exception:
                return datetime.datetime.min
        connected.sort(key=lambda s: (_iso_to_dt(s.get("last_heartbeat_at")), _iso_to_dt(s.get("updated_at"))), reverse=True)
        return connected[0], None

    if status is None:
        status = "active"
    if status not in ("active", "deleted"):
        return _err("VALIDATION_ERROR", "status must be 'active' or 'deleted'.")
    if package_path is not None and not isinstance(package_path, str):
        return _err("VALIDATION_ERROR", "package_path must be a string or null.")
    if path_prefix is not None and not isinstance(path_prefix, str):
        return _err("VALIDATION_ERROR", "path_prefix must be a string or null.")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string or null.")

    sess, serr = _resolve_session(session_id)

    invs = _load(inv_file)
    inv_id = f"ueinv_{uuid.uuid4().hex}"
    inv = {
        "id": inv_id,
        "session_id": (sess.get("id") if sess else "unknown"),
        "tool_name": "get_material_info",
        "request_params": {"session_id": session_id, "status": status, "package_path": package_path, "path_prefix": path_prefix, "limit": limit, "cursor": cursor},
        "status": "received",
        "result": None,
        "error": None,
        "started_at": now,
        "finished_at": None,
        "duration_ms": None,
        "python_code": None,
        "python_file": None,
        "ctx": None,
        "created_at": now,
        "updated_at": now,
    }
    invs.append(inv)
    _save(inv_file, invs)

    if serr:
        inv["status"] = "failed"
        inv["error"] = serr["error"]
        inv["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        inv["duration_ms"] = int((time.time() - t0) * 1000)
        inv["updated_at"] = inv["finished_at"]
        _save(inv_file, invs)
        return serr

    sess_id = sess.get("id")
    mats = _load(mats_file)
    rows = [m for m in mats if isinstance(m, dict) and m.get("session_id") == sess_id and m.get("status") == status]

    if package_path:
        rows = [m for m in rows if m.get("package_path") == package_path]
    if path_prefix:
        rows = [m for m in rows if isinstance(m.get("path"), str) and m["path"].startswith(path_prefix)]

    rows.sort(key=lambda r: (r.get("path") or "", r.get("id") or ""))

    start = 0
    if cursor:
        try:
            start = int(base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8"))
            if start < 0: start = 0
        except Exception:
            err = _err("VALIDATION_ERROR", "Invalid cursor.")
            inv["status"] = "failed"; inv["error"] = err["error"]
            inv["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            inv["duration_ms"] = int((time.time() - t0) * 1000); inv["updated_at"] = inv["finished_at"]
            _save(inv_file, invs)
            return err

    page = rows[start:start + limit]
    has_more = start + limit < len(rows)
    next_cursor = base64.urlsafe_b64encode(str(start + limit).encode("utf-8")).decode("utf-8") if has_more else None

    result = {"data": page, "total": len(rows), "has_more": has_more, "next_cursor": next_cursor}

    inv["status"] = "succeeded"
    inv["result"] = result
    inv["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    inv["duration_ms"] = int((time.time() - t0) * 1000)
    inv["updated_at"] = inv["finished_at"]
    _save(inv_file, invs)
    return result

def capture_scene_snapshot(session_id=None, wait=None, timeout_ms=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0099000" if __import__("os").path.isdir("./environment_mix/0099000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    inv_file = "ue_tool_invocations.json"
    sess_file = "ue_sessions.json"
    snaps_file = "ue_scene_snapshots.json"
    actors_file = "ue_actors.json"

    def _new_id(prefix):
        return f"{prefix}_01{uuid.uuid4().hex[:25].upper()}"

    def _iso_to_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _resolve_session(explicit_id):
        sessions = _load(sess_file)
        if explicit_id is not None:
            if not isinstance(explicit_id, str) or not explicit_id.strip():
                return None, _err("VALIDATION_ERROR", "session_id must be a string or null.", field="session_id")
            sid = explicit_id.strip()
            for s in sessions:
                if isinstance(s, dict) and s.get("id") == sid:
                    return s, None
            return None, _err("NOT_FOUND", "session_id not found.", session_id=sid)

        connected = [s for s in sessions if isinstance(s, dict) and s.get("status") == "connected" and isinstance(s.get("id"), str) and s.get("id")]
        if not connected:
            return None, _err("UNAUTHORIZED", "No connected Unreal session available to service this request.")
        # choose best by heartbeat/updated
        connected.sort(key=lambda s: (
            _iso_to_dt(s.get("last_heartbeat_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc),
            _iso_to_dt(s.get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc),
            _iso_to_dt(s.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc),
        ), reverse=True)
        return connected[0], None

    def _append_invocation(session_id_val, req_params):
        invs = _load(inv_file)
        inv = {
            "id": _new_id("ueinv"),
            "session_id": session_id_val,
            # Not in enum; log as closest
            "tool_name": "get_scene_info",
            "request_params": req_params,
            "status": "received",
            "result": None,
            "error": None,
            "started_at": None,
            "finished_at": None,
            "duration_ms": None,
            "python_code": None,
            "python_file": None,
            "ctx": None,
            "created_at": now,
            "updated_at": now,
        }
        invs.append(inv)
        _save(inv_file, invs)
        return inv["id"]

    def _patch_invocation(inv_id, patch):
        invs = _load(inv_file)
        for r in invs:
            if isinstance(r, dict) and r.get("id") == inv_id:
                r.update(patch)
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                _save(inv_file, invs)
                return True
        return False

    # Validate inputs
    if wait is None:
        wait = True
    if not isinstance(wait, bool):
        return _err("VALIDATION_ERROR", "wait must be a boolean.", field="wait")
    if timeout_ms is None:
        timeout_ms = 30000
    if not isinstance(timeout_ms, int) or timeout_ms < 1000 or timeout_ms > 120000:
        return _err("VALIDATION_ERROR", "timeout_ms must be an integer between 1000 and 120000.", field="timeout_ms")

    session, serr = _resolve_session(session_id)
    if serr:
        return serr
    sid = session["id"]

    inv_id = _append_invocation(sid, {"session_id": session_id, "wait": wait, "timeout_ms": timeout_ms})
    started = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _patch_invocation(inv_id, {"status": "running", "started_at": started})

    snaps = _load(snaps_file)

    snap = {
        "id": _new_id("ue_snap"),
        "session_id": sid,
        "status": "capturing",
        "scene_payload": None,
        "actor_count": None,
        "captured_at": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    snaps.append(snap)
    _save(snaps_file, snaps)

    if not wait:
        resp = {"snapshot": snap, "duration_ms": int(max(0, round((time.time() - t0) * 1000)))}
        finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _patch_invocation(inv_id, {"status": "succeeded", "result": resp, "finished_at": finished, "duration_ms": resp["duration_ms"]})
        return resp

    # Simulate capture completion immediately (offline): compute active actor count and minimal payload.
    actors = _load(actors_file)
    active_count = sum(1 for a in actors if isinstance(a, dict) and a.get("session_id") == sid and a.get("status") == "active")
    payload = {
        "session_id": sid,
        "captured_by": "capture_scene_snapshot",
        "actor_count": active_count,
        "map_name": session.get("map_name"),
        "map_path": session.get("map_path"),
        "project_name": session.get("project_name"),
        "engine_version": session.get("engine_version"),
    }

    # Transition capturing -> ready
    snap["status"] = "ready"
    snap["scene_payload"] = payload
    snap["actor_count"] = active_count
    snap["captured_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    snap["updated_at"] = snap["captured_at"]
    _save(snaps_file, snaps)

    resp = {"snapshot": snap, "duration_ms": int(max(0, round((time.time() - t0) * 1000)))}
    finished = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _patch_invocation(inv_id, {"status": "succeeded", "result": resp, "finished_at": finished, "duration_ms": resp["duration_ms"]})
    return resp
